import{z as i,x as B,o as E,c as l,q as t,j as o,D as e,d as r,s,S as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"基本面数据与重述","description":"","frontmatter":{"title":"基本面数据与重述","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fundamentals-restatements.md","filePath":"quant/fundamentals-restatements.md","lastUpdated":1791063341000}'),d={name:"quant/fundamentals-restatements.md"};function p(m,a,c,C,u,h){const n=B("Mermaid");return E(),l("div",null,[a[2]||(a[2]=t('<h1 id="基本面数据与重述" tabindex="-1">基本面数据与重述 <a class="header-anchor" href="#基本面数据与重述" aria-label="Permalink to &quot;基本面数据与重述&quot;">​</a></h1><div class="epigraph"><p>财报有初值与此后多次重述。用今天的 Compustat 行去模拟十年前的决策，等于让当时的组合经理读到未来的更正。</p><footer>—— Croushore and Stark, A real-time data set for macroeconomists, Journal of Econometrics, 2001；Hennes, Leone and Miller, The Importance of Distinguishing Errors from Irregularities in Restatement Research, TAR, 2008</footer></div><p><a href="/quant/taq-processing">上一课</a>处理高频磁带。<a href="/quant/crsp-compustat">CRSP 对齐</a>已要求按可知日连接会计。本课的缺口是<strong>同一会计科目的版本</strong>：重述、差错更正与舞弊更正。Hennes、Leone 与 Miller（2008）强调把差错与违规分开，否则重述样本的经济含义被混在一起。Croushore–Stark 在宏观上证明修订改变政策规则结论；微观会计同一机制。后课分析师共识是另一条「当时可知」的盈利路径，常比定稿更早。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>供应商终端里的盈利、营收、资产负债，默认是最新修订后的数字。点-in-time 数据库则保留每个字段的 <code>value</code>、<code>as_of</code>、<code>vintage</code>。没有 vintage，价值因子、应计、盈利动量都可能含前视：重述若把去年盈利调低，事后面板在「当时」就已经调低，策略会避开或做空一个当时市场上尚未知道的污点。问题是定义可知集：SEC 提交日、新闻稿日、供应商入库日，三者可以差很多天。应选用策略当时能订阅的那一个，并在文档里写死。</p><p><span class="marginnote">直觉类比：vintage 像照片，供应商终端默认给你的是事后修饰过的画像。用画像回测，等于让 2015 年的组合经理读到 2018 年才完成的更正——画像越「干净」，回测越假。</span></p><p>重述原因不同。会计差错、准则变化、与欺诈调查，对后续收益与诉讼风险不同。把所有重述当同一哑元，事件研究的平均处理效应没有对象。Hennes 等提供的分类是一种可引用的划分，不是唯一划分，但必须有划分。</p>',7)),(E(),o(A,null,{default:e(()=>[s(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RE%5B%22%E4%B8%80%E6%AC%A1%E9%87%8D%E8%BF%B0%E5%85%AC%E5%91%8A%22%5D%20--%3E%20ERR%5B%22%E5%B7%AE%E9%94%99%E6%9B%B4%E6%AD%A3%EF%BC%9A%E4%BC%9A%E8%AE%A1%E4%BC%B0%E8%AE%A1%E6%88%96%E8%AE%A1%E7%AE%97%E9%94%99%E8%AF%AF%22%5D%0A%20%20RE%20--%3E%20GAAP%5B%22%E5%87%86%E5%88%99%E5%88%87%E6%8D%A2%EF%BC%9A%E6%96%B0%E5%87%86%E5%88%99%E8%A6%81%E6%B1%82%E7%9A%84%E5%8F%A3%E5%BE%84%E5%8F%98%E5%8C%96%22%5D%0A%20%20RE%20--%3E%20FRD%5B%22%E8%BF%9D%E8%A7%84%E8%B0%83%E6%9F%A5%EF%BC%9A%E8%88%9E%E5%BC%8A%E5%AB%8C%E7%96%91%22%5D%0A%20%20ERR%20--%3E%20E1%5B%22%E5%90%8E%E6%9E%9C%EF%BC%9A%E5%A4%9A%E4%B8%BA%E6%95%B0%E6%8D%AE%E9%97%AE%E9%A2%98%EF%BC%8C%E5%90%8E%E7%BB%AD%E5%8F%AF%E9%A2%84%E6%B5%8B%E6%80%A7%E5%BC%B1%22%5D%0A%20%20GAAP%20--%3E%20G1%5B%22%E5%90%8E%E6%9E%9C%EF%BC%9A%E7%BB%93%E6%9E%84%E6%96%AD%E7%82%B9%EF%BC%8C%E6%A0%B7%E6%9C%AC%E9%A1%BB%E5%88%86%E6%AE%B5%22%5D%0A%20%20FRD%20--%3E%20F1%5B%22%E5%90%8E%E6%9E%9C%EF%BC%9A%E8%AF%89%E8%AE%BC%E4%B8%8E%E9%80%80%E5%B8%82%E9%A3%8E%E9%99%A9%EF%BC%8C%E5%90%8E%E7%BB%AD%E6%94%B6%E7%9B%8A%E6%98%BE%E8%91%97%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20E1%20--%3E%20Z%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%93%91%E5%85%83%E6%A6%82%E6%8B%AC%E4%B8%8D%E4%BA%86%E4%B8%89%E7%B1%BB%EF%BC%9A%E5%85%88%E5%88%86%E7%B1%BB%E5%86%8D%E7%A0%94%E7%A9%B6%22%5D%0A%20%20G1%20--%3E%20Z%0A%20%20F1%20--%3E%20Z%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">数字实例：公司 2 月 26 日新闻稿初值 EPS 0.80 元，3 月底 10-K 定稿 0.78 元，供应商 4 月 2 日入库。做 3 月 1 日的回测只能用 0.80——尽管「最终正确」的是 0.78。三个日期相差一个多月，选错一个就是前视。</span></p><h3 id="初步盈利、10-q-10-k-与供应商标准化" tabindex="-1">初步盈利、10-Q/10-K 与供应商标准化 <a class="header-anchor" href="#初步盈利、10-q-10-k-与供应商标准化" aria-label="Permalink to &quot;初步盈利、10-Q/10-K 与供应商标准化&quot;">​</a></h3><p>公司新闻稿的初步数、监管文本中的数、Compustat 标准化后的数，口径不同：非公认会计科目、一次性项目处理、合并范围。因子若混用 IBES 实际值与 Compustat，SUE 的分母会错。本课管供应商会计版本；下一课管分析师路径。两者的「实际盈利」字段不要同名不同义。</p><p><span class="marginnote">A 股对应的是公告日、定期报告、事后更正公告与问询函。更正公告是公开的 vintage。用最新年报回填三年前的季度因子，同样是前视。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>存储：会计事实表以 <code>(gvkey, period, item, vintage_ts)</code> 为主键。查询 API 只接受 <code>as_of</code>，返回当时已发布的最新 vintage。回测日 \\(t\\) 的账面市值用 \\(t\\) 日可知的账面，而不是用财政年度结束后供应商最终版。宏观对照：不要用修订后 GDP 去训当时的交易规则，Croushore–Stark 数据集是模板。</p><p>事件研究：重述公告日是事件，不是 <code>datadate</code>。分类：差错 vs 违规（或监管调查）。控制同期市场与行业。把重述当特征进入截面因子时，只能用公告后的信息，并注意稀疏与选择——会重述的公司不是随机样本。</p><h3 id="与退市、并购的交互" tabindex="-1">与退市、并购的交互 <a class="header-anchor" href="#与退市、并购的交互" aria-label="Permalink to &quot;与退市、并购的交互&quot;">​</a></h3><p>重述常伴随退市或并购，链接表同时失效。流水线应在重述窗口检查 CCM 是否仍有效，避免把继承主体的新会计接到旧 permno 上。这是上一课链接问题的动态版。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前视重述让策略在信息集之外选择。样本内 IC 变好，因为「质量」被未来的审计意见擦干净了。样本外失效，因为实盘读不到未来 8-K。宏观实时数据文献把这称为实时 vs 修订；交易台上名字叫 point-in-time。机制不新，只是会计科目比 GDP 更多、更易被终端「帮你更新」。</p><p>应计异常、盈利质量一类策略对会计应计定义敏感。定义若建立在最终版应计上，而交易建立在初值上，异常的可交易性被高估。应在 PIT 数据上重新估计，而不是只换一个供应商名字。</p><p><span class="marginnote">为什么重要：应计与盈利质量策略的利润本来就薄，全靠「当时真的看不到污点」这一点。数据被终端静默更新后，样本内 IC 被未来的审计意见擦亮，实盘一上线就失效——而且回测从没见过真实世界，你连哪里错了都查不到。</span></p>',13)),(E(),o(A,null,{default:e(()=>[s(n,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20Prelim%5B%22%E6%96%B0%E9%97%BB%E7%A8%BF%E5%88%9D%E5%80%BC%22%5D%20--%3E%20V1%5B%22vintage%201%22%5D%0A%20%20Fil%5B%22%E5%AE%9A%E6%9C%9F%E6%8A%A5%E5%91%8A%22%5D%20--%3E%20V2%5B%22vintage%202%22%5D%0A%20%20Rest%5B%22%E9%87%8D%E8%BF%B0%E5%85%AC%E5%91%8A%22%5D%20--%3E%20V3%5B%22vintage%203%22%5D%0A%20%20AsOf%5B%22%E6%9F%A5%E8%AF%A2%20as-of%20%3D%20t%22%5D%20--%3E%20Pick%5B%22t%20%E6%97%A5%E5%B7%B2%E5%AD%98%E5%9C%A8%E7%9A%84%E6%9C%80%E6%96%B0%20vintage%22%5D%0A%20%20V1%20--%3E%20Pick%0A%20%20V2%20--%3E%20Pick%0A%20%20V3%20--%3E%20Pick%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论如何利用未公开的重述信息或抢披露。供应商之间的标准化差异会使「同一科目」不可横比，对照见后课数据商。非美 GAAP/IFRS 切换是结构断点，须分段而不是静默重述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>会计必须带 vintage；用最终版回测是前视。</li><li>重述要分差错与违规；事件日是公告日。</li><li>查询接口强制 as-of，与宏观实时数据同一纪律。</li><li>出处：Croushore and Stark, <em>Journal of Econometrics</em>, 2001；Hennes, Leone and Miller, <em>TAR</em>, 2008。</li></ul>',4))])}const f=i(d,[["render",p]]);export{D as __pageData,f as default};
